from itertools import combinations, permutations

names = ["Garza", "Yates", "Zimmer", "Flores", "Lynch", "King", "Meyer", "Ortiz"]
cls = [1, 3, 3, 1, 2, 2, 2, 2]
idx = {n: i for i, n in enumerate(names)}
R, S, T = 0, 1, 2
start = (R, R, R, S, S, T, T, T)

def moves(st):
    for X, Y in permutations(range(3), 2):
        xs = [i for i in range(8) if st[i] == X]
        ys = [i for i in range(8) if st[i] == Y]
        # 1-for-1 same class
        for b in xs:
            for c in ys:
                if cls[b] == cls[c]:
                    s = list(st); s[b] = Y; s[c] = X
                    yield tuple(s)
        # X gives one of class k, Y gives two of class k+1
        for k in (1, 2):
            for b in xs:
                if cls[b] != k:
                    continue
                for c, d in combinations(ys, 2):
                    if cls[c] == k + 1 and cls[d] == k + 1:
                        s = list(st); s[b] = Y; s[c] = X; s[d] = X
                        yield tuple(s)

seen = {start}
stack = [start]
while stack:
    st = stack.pop()
    for n in moves(st):
        if n not in seen:
            seen.add(n)
            stack.append(n)

print("reachable states:", len(seen))

def owns(st, comp, bl):
    return {names[i] for i in range(8) if st[i] == comp} == set(bl)

opts = {
    "A": lambda st: owns(st, R, ["Lynch", "Meyer", "Ortiz"]),
    "B": lambda st: owns(st, S, ["Garza", "Meyer"]),
    "C": lambda st: owns(st, S, ["King", "Meyer", "Ortiz"]),
    "D": lambda st: owns(st, T, ["Flores", "Yates"]),
    "E": lambda st: owns(st, T, ["Garza", "Lynch"]),
}
cannot = []
for k, f in opts.items():
    ok = any(f(s) for s in seen)
    print(k, "reachable" if ok else "NOT reachable")
    if not ok:
        cannot.append(k)

print("Cannot be true:", cannot)
print("Claimed answer: A")
if cannot == ["A"]:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
